import{_ as t,o as r,c as a,ag as o}from"./chunks/framework.cyF4XceO.js";const p=JSON.parse('{"title":"Edge Platform Family proposals","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/edge/index.md","filePath":"proposals/edge/index.md"}'),d={name:"proposals/edge/index.md"};function i(n,e,s,c,l,m){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="edge-platform-family-proposals" tabindex="-1">Edge Platform Family proposals <a class="header-anchor" href="#edge-platform-family-proposals" aria-label="Permalink to &quot;Edge Platform Family proposals&quot;">​</a></h1><p>The Edge Platform Family, <code>edge.forms.takoform.com</code>, is the first official Form Family (<a href="./../../spec/decisions/0009-form-families-and-namespaced-api-versions.html">decision 0009</a>). Its members fix, completely, the application-visible semantics of a proven edge developer platform without naming its vendor (<a href="./../../spec/decisions/0008-forms-preserve-service-shape.html">decision 0008</a>).</p><h2 id="authoring-policy-shape-preserving-contracts" tabindex="-1">Authoring policy: shape-preserving contracts <a class="header-anchor" href="#authoring-policy-shape-preserving-contracts" aria-label="Permalink to &quot;Authoring policy: shape-preserving contracts&quot;">​</a></h2><p>Every member Form preserves one service shape end to end: execution ABI, client API, data model, consistency, delivery guarantees, update and delete units, error semantics, and the capabilities exposed through typed Bindings. No free semantic token is admitted; a difference in semantics is a different Form, never a selector value. Outward capability use is a digest-bound Binding held by a revision resource; inward activation is an attachment resource (<a href="./../../spec/decisions/0010-exact-interface-and-binding-contracts.html">decision 0010</a>). Desired schemas carry no <code>name</code> or envelope plumbing: the Host API v1 resource envelope owns identity and status (<a href="./../../spec/decisions/0011-resource-identity-generation-and-revision.html">decision 0011</a>).</p><p>The catalog source of truth is <code>internal/edgeformcatalog</code>; the generated candidates live in <code>forms/candidates/edge.forms.takoform.com</code>, the exact Interface and Binding candidates in <code>interfaces/candidates/v1alpha1</code> and <code>bindings/candidates/v1alpha2</code>.</p><h2 id="current-roster-16-forms" tabindex="-1">Current roster: 16 Forms <a class="header-anchor" href="#current-roster-16-forms" aria-label="Permalink to &quot;Current roster: 16 Forms&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Form</th><th>Role</th><th>One-line semantics</th><th>Separate-Form boundary</th></tr></thead><tbody><tr><td><a href="./module-worker.html">ModuleWorker</a></td><td>identity</td><td>Logical identity of one ES Module Worker application; the ABI is fixed by identity.</td><td>A WASI function or container service is a different Form.</td></tr><tr><td><a href="./worker-bundle.html">WorkerBundle</a></td><td>revision</td><td>Immutable content-addressed module bundle: main module plus digest-pinned modules.</td><td>A different linking or packaging model is a different Form.</td></tr><tr><td><a href="./static-asset-bundle.html">StaticAssetBundle</a></td><td>revision</td><td>Immutable content-addressed static-file inventory.</td><td>Object storage or request routing is a separate Form.</td></tr><tr><td><a href="./worker-version.html">WorkerVersion</a></td><td>revision</td><td>Immutable executable snapshot: bundle, handlers, vars, sensitive slots, typed bindings.</td><td>Mutable in-place code or config is not a version of this Form.</td></tr><tr><td><a href="./worker-deployment.html">WorkerDeployment</a></td><td>deployment</td><td>Basis-point traffic split across up to eight Worker Versions of one worker.</td><td>Per-request routing rules or geographic steering is separate work.</td></tr><tr><td><a href="./worker-custom-domain.html">WorkerCustomDomain</a></td><td>attachment</td><td>Serves one DNS hostname from a worker&#39;s active deployment over HTTPS.</td><td>Path-pattern routes are a separate attachment Form.</td></tr><tr><td><a href="./worker-endpoint.html">WorkerEndpoint</a></td><td>attachment</td><td>Makes a worker reachable over HTTPS at an address the host assigns and publishes.</td><td>A name the author owns is <code>WorkerCustomDomain</code>; a chosen label or region is host placement, not a Form.</td></tr><tr><td><a href="./worker-cron-trigger.html">WorkerCronTrigger</a></td><td>attachment</td><td>Invokes the scheduled handler on a five-field UTC cron schedule.</td><td>Timezone-aware scheduling is a different Form.</td></tr><tr><td><a href="./edge-kv-namespace.html">EdgeKVNamespace</a></td><td>identity</td><td>Globally replicated key/value namespace with eventual consistency.</td><td>A linearizable or per-key-consistent store is a different Form.</td></tr><tr><td><a href="./sqlite-database.html">SQLiteDatabase</a></td><td>identity</td><td>Embedded SQLite database with safe wire values, rollback-only queries, and serializable transactions.</td><td>A Postgres or MySQL database is a different Form.</td></tr><tr><td><a href="./sqlite-migration-set.html">SQLiteMigrationSet</a></td><td>revision</td><td>Immutable ordered application/sql migration manifest.</td><td>Another dialect or declarative schema model is a different Form.</td></tr><tr><td><a href="./sqlite-migration-application.html">SQLiteMigrationApplication</a></td><td>attachment</td><td>Applies only the checksum-safe suffix of one set to one database.</td><td>Rollback or destructive reset requires a separate authority-bearing Form.</td></tr><tr><td><a href="./at-least-once-queue.html">AtLeastOnceQueue</a></td><td>identity</td><td>Queue with at-least-once delivery and no ordering guarantee.</td><td>A FIFO or exactly-once queue is a different Form.</td></tr><tr><td><a href="./queue-consumer.html">QueueConsumer</a></td><td>attachment</td><td>Attaches one worker as the batch consumer of one queue, with retry and dead-lettering.</td><td>Pull-based consumption over an API is a different Form.</td></tr><tr><td><a href="./durable-workflow.html">DurableWorkflow</a></td><td>identity</td><td>Code-defined durable workflow instances with memoized replay and bounded execution.</td><td>A generic queue job or scheduler is a different contract.</td></tr><tr><td><a href="./actor-namespace.html">ActorNamespace</a></td><td>identity</td><td>Addressable actor id space with per-id execution, storage, and alarms.</td><td>A provisioned object-storage bucket is not an actor namespace.</td></tr></tbody></table><p><a href="./object-bucket.html"><code>ObjectBucket</code></a>, <code>edge.objects</code>, and <code>module-worker.object-bucket</code> are retained Provider 2.1.1/v1beta1 history, not members of this current roster. Object storage consumed by current worker code is represented, when appropriate, as a sealed <code>standards.takoform.com/v1</code> slot with an opaque reverse-DNS protocol identifier. That slot creates no bucket Resource and Takoform maintains no protocol enum.</p><p>Container, Function, Pull Queue, Schedule, Table, Topic, and Vector semantics now live in their own versionless current family groups, per <a href="./../../spec/form-families.html">spec/form-families.md</a>. A prose proposal list is not an identity registry; the generated current-family index closes the exact candidate corpus.</p>',9)])])}const u=t(d,[["render",i]]);export{p as __pageData,u as default};
